canonical:
class Coordinate:
    def __init__(self, lat, lng):
        self.lat = lat
        self.lng = lng

    def __repr__(self):
        return f'Coordinate({self.lat}, {self.lng})'

    def __eq__(self, other):
        return self.lat == other.lat and self.lng == other.lng
